async function updateDeletion(
	db: DatabaseExecutor,
	claim: MediaUsageCollectionDeletionRecord & { leaseToken: string },
	values: Updateable<MediaUsageCollectionDeletionTable>,
): Promise<void> {
	const result = await db
		.updateTable("_emdash_media_usage_collection_deletions")
		.set({
			...values,
			attempt_count: 0,
			last_error_code: null,
			updated_at: collectionDeletionCurrentTimestamp(db),
		})
		.where("collection_id", "=", claim.collectionId)
		.where("state", "=", "leased")
		.where("lease_token", "=", claim.leaseToken)
		.where(liveLeaseGuard(db, claim))
		.executeTakeFirst();
	if (Number(result.numUpdatedRows ?? 0) !== 1)
		throw new Error("Collection deletion lease was lost");
}

function liveLeaseGuard(
	db: DatabaseExecutor,
	claim: Pick<MediaUsageCollectionDeletionRecord, "collectionId"> & { leaseToken: string },
): RawBuilder<boolean> {
	return isPostgres(db)
		? sql<boolean>`EXISTS (
			SELECT 1 FROM _emdash_media_usage_collection_deletions AS deletion
			WHERE deletion.collection_id = ${claim.collectionId}
				AND deletion.state = 'leased'
				AND deletion.lease_token = ${claim.leaseToken}
				AND deletion.lease_expires_at::timestamptz > clock_timestamp()
		)`
		: sql<boolean>`EXISTS (
			SELECT 1 FROM _emdash_media_usage_collection_deletions AS deletion
			WHERE deletion.collection_id = ${claim.collectionId}
				AND deletion.state = 'leased'
				AND deletion.lease_token = ${claim.leaseToken}
				AND deletion.lease_expires_at > strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
		)`;
}

function retryDelaySeconds(attemptCount: number): number {
	return Math.min(
		MEDIA_USAGE_COLLECTION_DELETION_LIMITS.retryMaxSeconds,
		MEDIA_USAGE_COLLECTION_DELETION_LIMITS.retryBaseSeconds * 2 ** attemptCount,
	);
}

export async function processDueMediaUsageReconciliation(
	db: Kysely<Database>,
): Promise<MediaUsageReconciliationOutcome> {
	return (await processDueMediaUsageReconciliationDetailed(db)).outcome;
}

export async function processDueMediaUsageReconciliationDetailed(
	db: Kysely<Database>,
	options: ProcessDueMediaUsageReconciliationOptions = {},
): Promise<MediaUsageReconciliationDetailedResult> {
	if (!options.activationKnownActive) {
		const activation = await db
			.selectFrom("_emdash_media_usage_activation")
			.select("state")
			.where("task_key", "=", "incremental_capture")
			.executeTakeFirst();
		if (activation?.state !== "active") {
			return { outcome: "inactive", consumedUnit: false, hasDeferredCandidate: false };
		}
	}

	const reconciliation = new MediaUsageReconciliationRepository(db);
	if (await reconciliation.deleteOneObsolete()) {
		return { outcome: "completed", consumedUnit: true, hasDeferredCandidate: false };
	}
	const [failed] = await reconciliation.findFailed(1);
	if (failed) {
		if (await reconciliation.finishFailedCoverage(failed.collectionId, failed.runToken)) {
			return { outcome: "failed", consumedUnit: true, hasDeferredCandidate: false };
		}
		if (await reconciliation.resetFailedForNewEpoch(failed)) {
			return { outcome: "advanced", consumedUnit: true, hasDeferredCandidate: false };
		}
	}

	const seeded = await reconciliation.seedNextCandidate();
	const candidates = await reconciliation.findDue(
		MEDIA_USAGE_RECONCILIATION_LIMITS.candidatesPerTick,
	);
	let claim: MediaUsageReconciliationClaim | null = null;
	for (const candidate of candidates) {
		claim = await reconciliation.claim({
			collectionId: candidate.collectionId,
			runToken: candidate.runToken,
			leaseDurationSeconds: MEDIA_USAGE_RECONCILIATION_LIMITS.leaseDurationSeconds,
		});
		if (claim) break;
	}
	if (!claim) {
		return {
			outcome: candidates.length === 0 ? "not_due" : "claim_lost",
			consumedUnit: seeded,
			hasDeferredCandidate:
				candidates.length === 0 && (await reconciliation.hasDeferredCandidate()),
		};
	}

	try {
		return {
			outcome: await processClaimedReconciliation(db, claim),
			consumedUnit: true,
			hasDeferredCandidate: false,
		};
	} catch (error) {
		const terminal = claim.attemptCount + 1 >= MEDIA_USAGE_RECONCILIATION_LIMITS.maxAttempts;
		const recorded = await reconciliation.recordFailure({
			collectionId: claim.collectionId,
			runToken: claim.runToken,
			leaseToken: claim.leaseToken,
			errorCode: "MEDIA_USAGE_RECONCILIATION_FAILED",
			retryDelaySeconds: retryDelaySeconds(claim.attemptCount),
			terminal,
		});
		if (!recorded) {
			return { outcome: "claim_lost", consumedUnit: true, hasDeferredCandidate: false };
		}
		if (terminal) await reconciliation.finishFailedCoverage(claim.collectionId, claim.runToken);
		console.error("[media-usage:reconciliation] Processing failed:", error);
		return {
			outcome: terminal ? "failed" : "retry",
			consumedUnit: true,
			hasDeferredCandidate: false,
		};
	}
}

export async function processClaimedMediaUsageReconciliationScan(
	db: Kysely<Database>,
	claim: MediaUsageReconciliationClaim,
	options: { releaseOnExhausted?: boolean } = {},
	knownCurrent?: MediaUsageReconciliationRecord,
): Promise<MediaUsageReconciliationScanOutcome> {
	const reconciliation = new MediaUsageReconciliationRepository(db);
	let current =
		knownCurrent ?? (await reconciliation.findByIdentity(claim.collectionId, claim.runToken));
	if (!current || current.leaseToken !== claim.leaseToken || current.phase !== "scan") {
		return "deferred";
	}

	let fields;
	let fieldFingerprint: string;
	if (current.targetEpoch === null) {
		const targetEpoch = await reconciliation.beginRun(claim);
		if (targetEpoch === null) {
			await reconciliation.release({ ...claim, delaySeconds: 30 });
			return "deferred";
		}
		fields = await loadContentMediaUsageFields(db, claim.collectionSlug, claim.collectionId);
		fieldFingerprint = await buildContentMediaUsageFieldFingerprint(fields);
		const scanUpperId =
			fields.extractionFields.length === 0 ? null : await reconciliation.findScanUpperId(claim);
		if (
			!(await reconciliation.initializeScan({
				claim,
				targetEpoch,
				fieldFingerprint,
				scanUpperId,
			}))
		) {
			return "deferred";
		}
		current = {
			...current,
			targetEpoch,
			fieldFingerprint,
			scanCursor: null,
			scanUpperId,
			sourceCursor: null,
			sourceUpperKey: null,
		};
	} else {
		fields = await loadContentMediaUsageFields(db, claim.collectionSlug, claim.collectionId);
		fieldFingerprint = await buildContentMediaUsageFieldFingerprint(fields);
	}

	if (current.fieldFingerprint !== fieldFingerprint || current.targetEpoch === null) {
		return "restart_required";
	}
	const contentIds = await reconciliation.findScanPage(
		current,
		MEDIA_USAGE_RECONCILIATION_LIMITS.scanPageSize,
	);
	if (contentIds.length === 0) {
		if (options.releaseOnExhausted ?? true) {
			await reconciliation.release({ ...claim, delaySeconds: 30 });
		}
		return "exhausted";
	}

	const work = new MediaUsageWorkRepository(db);
	await work.enqueueReconciliationPage({
		collectionId: claim.collectionId,
		collectionSlug: claim.collectionSlug,
		runToken: claim.runToken,
		leaseToken: claim.leaseToken,
		changeEpoch: current.targetEpoch,
		phase: "scan",
		contentIds,
	});
	const nextCursor = contentIds.at(-1)!;
	if (
		!(await reconciliation.checkpointScan({
			claim,
			targetEpoch: current.targetEpoch,
			previousCursor: current.scanCursor,
			nextCursor,
		}))
	) {
		return "deferred";
	}
	if (!(await reconciliation.release({ ...claim, delaySeconds: 0 }))) return "deferred";
	return "advanced";
}

async function processClaimedReconciliation(
	db: Kysely<Database>,
	claim: MediaUsageReconciliationClaim,
): Promise<MediaUsageReconciliationOutcome> {
	const reconciliation = new MediaUsageReconciliationRepository(db);
	let current: MediaUsageReconciliationRecord = claim;
	if (current.targetEpoch !== null && !(await reconciliation.ownsRun(claim, current.targetEpoch))) {
		return restartReconciliation(db, reconciliation, claim, current);
	}
	if (current.targetEpoch !== null) {
		await new MediaUsageWorkRepository(db).deleteObsoleteReconciliationWork({
			collectionId: claim.collectionId,
			collectionSlug: claim.collectionSlug,
			runToken: claim.runToken,
			leaseToken: claim.leaseToken,
			targetEpoch: current.targetEpoch,
		});
	}

	if (current.phase === "scan") {
		const outcome = await processClaimedMediaUsageReconciliationScan(
			db,
			claim,
			{
				releaseOnExhausted: false,
			},
			current,
		);
		if (outcome === "restart_required") {
			current =
				(await reconciliation.findByIdentity(claim.collectionId, claim.runToken)) ?? current;
			return restartReconciliation(db, reconciliation, claim, current);
		}
		if (outcome !== "exhausted") return outcome;
		if (current.targetEpoch === null || current.fieldFingerprint === null) {
			current =
				(await reconciliation.findByIdentity(claim.collectionId, claim.runToken)) ?? current;
		}
		const barrier = await reconciliation.findWorkBarrier(claim.collectionId);
		if (barrier.state === "failed") {
			return failReconciliation(reconciliation, claim, barrier.errorCode, true);
		}
		if (barrier.state === "pending") {
			await reconciliation.release({ ...claim, delaySeconds: 30 });
			return "deferred";
		}
		if (current.targetEpoch === null || current.fieldFingerprint === null) return "claim_lost";
		const sourceUpperKey = await reconciliation.findSourceUpperKey(claim, current.targetEpoch);
		if (
			!(await reconciliation.transitionToSources({
				claim,
				targetEpoch: current.targetEpoch,
				fieldFingerprint: current.fieldFingerprint,
				sourceUpperKey,
			}))
		) {
			return "claim_lost";
		}
		if (!(await reconciliation.release({ ...claim, delaySeconds: 0 }))) return "claim_lost";
		return "advanced";
	}

	return processSourcePhase(db, reconciliation, claim, current);
}

async function processSourcePhase(
	db: Kysely<Database>,
	reconciliation: MediaUsageReconciliationRepository,
	claim: MediaUsageReconciliationClaim,
	current: MediaUsageReconciliationRecord,
): Promise<MediaUsageReconciliationOutcome> {
	if (current.targetEpoch === null || current.fieldFingerprint === null) return "claim_lost";
	const fields = await loadContentMediaUsageFields(db, claim.collectionSlug, claim.collectionId);
	const fieldFingerprint = await buildContentMediaUsageFieldFingerprint(fields);
	if (fieldFingerprint !== current.fieldFingerprint) {
		return restartReconciliation(db, reconciliation, claim, current, fields, fieldFingerprint);
	}

	const page = await reconciliation.findSourcePage(
		current,
		MEDIA_USAGE_RECONCILIATION_LIMITS.sourcePageSize,
	);
	if (page.length > 0) {
		let enqueuedMissingContent = false;
		const malformed = page.some(
			(source) =>
				!source.contentId ||
				(source.sourceVariant !== "columns" && source.sourceVariant !== "draft_overlay"),
		);
		if (malformed) {
			return failReconciliation(
				reconciliation,
				claim,
				"MEDIA_USAGE_RECONCILIATION_INVALID_SOURCE",
				false,
			);
		}
		const contentIds = [...new Set(page.map((source) => source.contentId!))];
		const enqueueIds =
			fields.extractionFields.length === 0
				? contentIds
				: await reconciliation.findMissingContentIds(claim.collectionSlug, contentIds);
		if (enqueueIds.length > 0) {
			await new MediaUsageWorkRepository(db).enqueueReconciliationPage({
				collectionId: claim.collectionId,
				collectionSlug: claim.collectionSlug,
				runToken: claim.runToken,
				leaseToken: claim.leaseToken,
				changeEpoch: current.targetEpoch,
				phase: "sources",
				contentIds: enqueueIds,
			});
			enqueuedMissingContent = true;
		}
		if (
			!(await reconciliation.checkpointSources({
				claim,
				targetEpoch: current.targetEpoch,
				previousCursor: current.sourceCursor,
				nextCursor: page.at(-1)!.sourceKey,
			}))
		) {
			return "claim_lost";
		}
		if (
			enqueuedMissingContent ||
			page.length === MEDIA_USAGE_RECONCILIATION_LIMITS.sourcePageSize
		) {
			if (!(await reconciliation.release({ ...claim, delaySeconds: 0 }))) return "claim_lost";
			return "advanced";
		}
	}

	const barrier = await reconciliation.findWorkBarrier(claim.collectionId);
	if (barrier.state === "failed") {
		return failReconciliation(reconciliation, claim, barrier.errorCode, true);
	}
	if (barrier.state === "pending") {
		await reconciliation.release({ ...claim, delaySeconds: 30 });
		return "deferred";
	}
	if (
		!(await reconciliation.finalizeCoverage({
			claim,
			targetEpoch: current.targetEpoch,
			fieldFingerprint,
			schemaVersion: CONTENT_SOURCE_SCHEMA_VERSION,
		}))
	) {
		return "claim_lost";
	}
	if (!(await reconciliation.deleteFinalized(claim))) return "claim_lost";
	return "completed";
}

async function restartReconciliation(
	db: Kysely<Database>,
	reconciliation: MediaUsageReconciliationRepository,
	claim: MediaUsageReconciliationClaim,
	current: MediaUsageReconciliationRecord,
	fields?: Awaited<ReturnType<typeof loadContentMediaUsageFields>>,
	fieldFingerprint?: string,
): Promise<MediaUsageReconciliationOutcome> {
	if (current.targetEpoch === null) return "claim_lost";
	const discoveredFields =
		fields ?? (await loadContentMediaUsageFields(db, claim.collectionSlug, claim.collectionId));
	const fingerprint =
		fieldFingerprint ?? (await buildContentMediaUsageFieldFingerprint(discoveredFields));
	const targetEpoch = await reconciliation.restartRun(claim, current.targetEpoch);
	if (targetEpoch === null) {
		await reconciliation.release({ ...claim, delaySeconds: 30 });
		return "deferred";
	}
	const scanUpperId =
		discoveredFields.extractionFields.length === 0
			? null
			: await reconciliation.findScanUpperId(claim);
	if (
		!(await reconciliation.restartScan({
			claim,
			previousEpoch: current.targetEpoch,
			targetEpoch,
			fieldFingerprint: fingerprint,
			scanUpperId,
		}))
	) {
		return "claim_lost";
	}
	if (!(await reconciliation.release({ ...claim, delaySeconds: 0 }))) return "claim_lost";
	return "advanced";
}

async function failReconciliation(
	reconciliation: MediaUsageReconciliationRepository,
	claim: MediaUsageReconciliationClaim,
	errorCode: string,
	entryFailure: boolean,
): Promise<MediaUsageReconciliationOutcome> {
	const recorded = entryFailure
		? await reconciliation.recordEntryFailure(claim)
		: await reconciliation.recordFailure({
				collectionId: claim.collectionId,
				runToken: claim.runToken,
				leaseToken: claim.leaseToken,
				errorCode,
				retryDelaySeconds: 0,
				terminal: true,
			});
	if (!recorded) return "claim_lost";
	await reconciliation.finishFailedCoverage(claim.collectionId, claim.runToken);
	return "failed";
}

function retryDelaySeconds(attemptCount: number): number {
	const exponential = Math.min(
		MEDIA_USAGE_RECONCILIATION_LIMITS.retryMaxSeconds,
		MEDIA_USAGE_RECONCILIATION_LIMITS.retryBaseSeconds * 2 ** attemptCount,
	);
	const jitter = Math.floor(
		exponential * MEDIA_USAGE_RECONCILIATION_LIMITS.retryJitterRatio * Math.random(),
	);
	return Math.min(MEDIA_USAGE_RECONCILIATION_LIMITS.retryMaxSeconds, exponential + jitter);
}

export async function processMediaUsageWorkAfterWrite(
	db: Kysely<Database>,
	collectionSlug: string,
	contentId: string,
): Promise<MediaUsageWorkProcessingResult> {
	if (!(await isIncrementalCaptureActive(db))) {
		return { outcome: "inactive", claimed: false };
	}

	await new MediaUsageRepository(db).recoverIncrementalFinalizations();
	const repo = new MediaUsageWorkRepository(db);
	const work = await repo.findWorkForContent(collectionSlug, contentId);
	if (!work) return { outcome: "not_due", claimed: false };
	const claimed = await repo.claimWork({
		collectionId: work.collectionId,
		contentId: work.contentId,
		workVersion: work.workVersion,
		leaseDurationSeconds: MEDIA_USAGE_WORK_PROCESSING_LIMITS.leaseDurationSeconds,
	});
	if (!claimed) return { outcome: "claim_lost", claimed: false };
	try {
		const processed = await runClaimedBatch(db, [claimed]);
		return processed.get(workResultKey(claimed)) ?? { outcome: "claim_lost", claimed: false };
	} catch (error) {
		const transitioned = await repo.retryClaimedWorkBatch({
			work: [workLease(claimed)],
			errorCode: "MEDIA_USAGE_PROCESSING_FAILED",
			retryDelaySeconds: MEDIA_USAGE_WORK_PROCESSING_LIMITS.retryBaseSeconds,
			maxAttempts: MEDIA_USAGE_WORK_PROCESSING_LIMITS.maxAttempts,
		});
		const outcome = transitioned.get(workIdentityKey(claimed)) ?? "superseded";
		if (outcome === "failed") {
			await new MediaUsageRepository(db).recordIncrementalFailure({
				collectionId: claimed.collectionId,
				collectionSlug: claimed.collectionSlug,
				contentId: claimed.contentId,
				workVersion: claimed.workVersion,
				errorCode: "MEDIA_USAGE_PROCESSING_FAILED",
			});
		}
		console.error("[media-usage:work] Immediate processing failed:", error);
		return { outcome, claimed: true };
	}
}

export async function processDueMediaUsageWork(
	db: Kysely<Database>,
	options: ProcessDueMediaUsageWorkOptions = {},
): Promise<MediaUsageWorkTickResult> {
	const startedAt = Date.now();
	const result: MediaUsageWorkTickResult = {
		candidateCount: 0,
		claimedCount: 0,
		completedCount: 0,
		retryCount: 0,
		failedCount: 0,
		supersededCount: 0,
		obsoleteCount: 0,
		durationMs: 0,
	};

	if (!options.activationKnownActive && !(await isIncrementalCaptureActive(db))) {
		result.durationMs = Date.now() - startedAt;
		return result;
	}

	await new MediaUsageRepository(db).recoverIncrementalFinalizations();
	const repo = new MediaUsageWorkRepository(db);
	const candidates = await repo.claimDueWorkBatch({
		limit: MEDIA_USAGE_WORK_PROCESSING_LIMITS.candidatesPerTick,
		leaseDurationSeconds: MEDIA_USAGE_WORK_PROCESSING_LIMITS.leaseDurationSeconds,
	});
	result.candidateCount =
		candidates.length > 0 || !(await repo.hasNonterminalWork()) ? candidates.length : 1;

	const processedBatch = await processClaimedCollections(db, candidates);
	for (const candidate of candidates) {
		const processed = processedBatch.get(workResultKey(candidate)) ?? {
			outcome: "claim_lost" as const,
			claimed: false,
		};
		if (processed.claimed) result.claimedCount++;
		if (processed.outcome === "completed") result.completedCount++;
		if (processed.outcome === "retry") result.retryCount++;
		if (processed.outcome === "failed") result.failedCount++;
		if (processed.outcome === "superseded") result.supersededCount++;
		if (processed.outcome === "obsolete") result.obsoleteCount++;
	}

	result.durationMs = Date.now() - startedAt;
	return result;
}

async function processClaimedCollections(
	db: Kysely<Database>,
	candidates: readonly MediaUsageWorkRecord[],
): Promise<Map<string, MediaUsageWorkProcessingResult>> {
	const processed = new Map<string, MediaUsageWorkProcessingResult>();
	const byCollection = new Map<string, MediaUsageWorkRecord[]>();
	for (const candidate of candidates) {
		const key = collectionResultKey(candidate);
		const collection = byCollection.get(key) ?? [];
		collection.push(candidate);
		byCollection.set(key, collection);
	}
	for (const collection of byCollection.values()) {
		try {
			for (const [key, result] of await runClaimedBatch(db, collection)) {
				processed.set(key, result);
			}
		} catch (error) {
			for (const [key, result] of await retryFailedClaimedCollection(db, collection)) {
				processed.set(key, result);
			}
			console.error("[media-usage:work] Collection processing failed:", error);
		}
	}
	return processed;
}

async function retryFailedClaimedCollection(
	db: Kysely<Database>,
	candidates: readonly MediaUsageWorkRecord[],
): Promise<Map<string, MediaUsageWorkProcessingResult>> {
	const transitioned = await new MediaUsageWorkRepository(db).retryClaimedWorkBatch({
		work: candidates.map(workLease),
		errorCode: "MEDIA_USAGE_PROCESSING_FAILED",
		retryDelaySeconds: MEDIA_USAGE_WORK_PROCESSING_LIMITS.retryBaseSeconds,
		maxAttempts: MEDIA_USAGE_WORK_PROCESSING_LIMITS.maxAttempts,
	});
	const processed = new Map<string, MediaUsageWorkProcessingResult>();
	const failedCollectionIds = new Set<string>();
	for (const candidate of candidates) {
		const state = transitioned.get(workIdentityKey(candidate));
		if (state === "failed") failedCollectionIds.add(candidate.collectionId);
		processed.set(workResultKey(candidate), {
			outcome: state ?? "superseded",
			claimed: true,
		});
	}
	await new MediaUsageRepository(db).recordIncrementalFailuresByCollection({
		collectionIds: [...failedCollectionIds],
		errorCode: "MEDIA_USAGE_PROCESSING_FAILED",
	});
	return processed;
}

async function runClaimedBatch(
	db: Kysely<Database>,
	candidates: readonly MediaUsageWorkRecord[],
): Promise<Map<string, MediaUsageWorkProcessingResult>> {
	return isPostgres(db)
		? withTransaction(db, (trx) =>
				processClaimedBatch(trx, new MediaUsageWorkRepository(trx), candidates),
			)
		: processClaimedBatch(db, new MediaUsageWorkRepository(db), candidates);
}

calls.exactSourceCall:
withTransaction(db, (trx) =>
				processClaimedBatch(trx, new MediaUsageWorkRepository(trx), candidates),
			)

records.exactSourceFunction:
async function processClaimedBatch(
	db: Kysely<Database>,
	repo: MediaUsageWorkRepository,
	candidates: readonly MediaUsageWorkRecord[],
): Promise<Map<string, MediaUsageWorkProcessingResult>> {
	const results = new Map<string, MediaUsageWorkProcessingResult>();
	const locked = await repo.lockClaimedWorkBatch(candidates.map(workLease));
	const owned: MediaUsageWorkRecord[] = [];
	for (const candidate of candidates) {
		if (locked.has(workIdentityKey(candidate))) owned.push(candidate);
		else {
			results.set(workResultKey(candidate), { outcome: "superseded", claimed: true });
		}
	}
	const currentCollections = await findCurrentCollectionIdentities(db, owned);
	const current: MediaUsageWorkRecord[] = [];
	const obsolete: MediaUsageWorkRecord[] = [];
	for (const candidate of owned) {
		if (currentCollections.has(collectionResultKey(candidate))) current.push(candidate);
		else obsolete.push(candidate);
	}

	const obsoleteCompleted = await repo.completeWorkBatch(obsolete.map(workLease));
	for (const candidate of obsolete) {
		results.set(workResultKey(candidate), {
			outcome: obsoleteCompleted.has(workIdentityKey(candidate)) ? "obsolete" : "superseded",
			claimed: true,
		});
	}
	if (current.length === 0) return results;

	const refreshes = await refreshContentMediaUsageForWorkBatch(db, current, {
		shouldContinue: canContinueBulkWork,
	});
	const successful: MediaUsageWorkRecord[] = [];
	const unstarted: MediaUsageWorkRecord[] = [];
	const failedRefreshes: Array<{
		candidate: MediaUsageWorkRecord;
		refresh: ContentMediaUsageRefreshResult;
	}> = [];
	for (const candidate of current) {
		const refresh = refreshes.get(contentRefreshKey(candidate.collectionId, candidate.contentId));
		if (refresh?.success) successful.push(candidate);
		else if (!refresh) unstarted.push(candidate);
		else failedRefreshes.push({ candidate, refresh });
	}
	const terminalFailureCollections = new Map<string, Set<string>>();
	const failureGroups = new Map<
		string,
		{
			errorCode: string;
			retryDelaySeconds: number;
			terminal: boolean;
			candidates: MediaUsageWorkRecord[];
		}
	>();
	for (const failure of failedRefreshes) {
		const errorCode = processingErrorCode(failure.refresh.errorCode);
		const terminal =
			errorCode === "MEDIA_USAGE_RESOURCE_LIMIT" ||
			failure.candidate.attemptCount + 1 >= MEDIA_USAGE_WORK_PROCESSING_LIMITS.maxAttempts;
		const delay = retryDelaySeconds(failure.candidate.attemptCount);
		const key = `${errorCode}\u0000${terminal ? "terminal" : String(delay)}`;
		const group = failureGroups.get(key) ?? {
			errorCode,
			retryDelaySeconds: delay,
			terminal,
			candidates: [],
		};
		group.candidates.push(failure.candidate);
		failureGroups.set(key, group);
	}
	for (const group of failureGroups.values()) {
		const transitioned = await repo.retryClaimedWorkBatch({
			work: group.candidates.map(workLease),
			errorCode: group.errorCode,
			retryDelaySeconds: group.retryDelaySeconds,
			maxAttempts: group.terminal ? 1 : MEDIA_USAGE_WORK_PROCESSING_LIMITS.maxAttempts,
		});
		for (const candidate of group.candidates) {
			const state = transitioned.get(workIdentityKey(candidate));
			if (state === "failed") {
				const collections = terminalFailureCollections.get(group.errorCode) ?? new Set<string>();
				collections.add(candidate.collectionId);
				terminalFailureCollections.set(group.errorCode, collections);
			}
			results.set(workResultKey(candidate), {
				outcome: state ?? "superseded",
				claimed: true,
			});
		}
	}
	for (const [errorCode, collectionIds] of terminalFailureCollections) {
		await new MediaUsageRepository(db).recordIncrementalFailuresByCollection({
			collectionIds: [...collectionIds],
			errorCode,
		});
	}
	const released = await repo.releaseClaimedWorkBatch(unstarted.map(workLease));
	for (const candidate of unstarted) {
		results.set(workResultKey(candidate), {
			outcome: released.has(workIdentityKey(candidate)) ? "not_due" : "superseded",
			claimed: true,
		});
	}

	const usage = new MediaUsageRepository(db);
	const successfulByCollection = new Map<string, MediaUsageWorkRecord[]>();
	for (const candidate of successful) {
		const key = collectionResultKey(candidate);
		const collection = successfulByCollection.get(key) ?? [];
		collection.push(candidate);
		successfulByCollection.set(key, collection);
	}
	const readyToComplete: MediaUsageWorkRecord[] = [];
	const deferredCompletion: MediaUsageWorkRecord[] = [];
	const lostFinalization: MediaUsageWorkRecord[] = [];
	let pendingFinalizationQueries = 2;
	for (const collection of successfulByCollection.values()) {
		const first = collection[0];
		if (!first) continue;
		const metrics = getRequestContext()?.metrics;
		if (metrics && metrics.dbCount + pendingFinalizationQueries + 4 > 900) {
			deferredCompletion.push(...collection);
			continue;
		}
		const finalization = await usage.prepareIncrementalFinalization({
			collectionId: first.collectionId,
			collectionSlug: first.collectionSlug,
		});
		if (finalization.outcome !== "lost") {
			readyToComplete.push(...collection);
			pendingFinalizationQueries += 2;
			continue;
		}
		lostFinalization.push(...collection);
		pendingFinalizationQueries += 2;
	}
	const lostTransitions = await repo.retryClaimedWorkBatch({
		work: lostFinalization.map(workLease),
		errorCode: "MEDIA_USAGE_GENERATION_CONFLICT",
		retryDelaySeconds: MEDIA_USAGE_WORK_PROCESSING_LIMITS.retryBaseSeconds,
		maxAttempts: MEDIA_USAGE_WORK_PROCESSING_LIMITS.maxAttempts,
	});
	const lostFailedCollections = new Set<string>();
	for (const candidate of lostFinalization) {
		const state = lostTransitions.get(workIdentityKey(candidate));
		if (state === "failed") lostFailedCollections.add(candidate.collectionId);
		results.set(workResultKey(candidate), {
			outcome: state ?? "superseded",
			claimed: true,
		});
	}
	await usage.recordIncrementalFailuresByCollection({
		collectionIds: [...lostFailedCollections],
		errorCode: "MEDIA_USAGE_GENERATION_CONFLICT",
	});
	const deferred = await repo.releaseClaimedWorkBatch(deferredCompletion.map(workLease));
	for (const candidate of deferredCompletion) {
		results.set(workResultKey(candidate), {
			outcome: deferred.has(workIdentityKey(candidate)) ? "not_due" : "superseded",
			claimed: true,
		});
	}
	const completed = await repo.completeWorkBatch(readyToComplete.map(workLease));
	const completedCollections = new Map<string, MediaUsageWorkRecord>();
	for (const candidate of readyToComplete) {
		const didComplete = completed.has(workIdentityKey(candidate));
		results.set(workResultKey(candidate), {
			outcome: didComplete ? "completed" : "superseded",
			claimed: true,
		});
		if (didComplete) completedCollections.set(collectionResultKey(candidate), candidate);
	}
	for (const collection of completedCollections.values()) {
		await usage.recordIncrementalSuccess({
			collectionId: collection.collectionId,
			collectionSlug: collection.collectionSlug,
		});
	}
	return results;
}

async function findCurrentCollectionIdentities(
	db: Kysely<Database>,
	candidates: readonly MediaUsageWorkRecord[],
): Promise<Set<string>> {
	const identities = new Map(
		candidates.map((candidate) => [collectionResultKey(candidate), candidate] as const),
	);
	const current = new Set<string>();
	for (const batch of chunkCollectionIds(
		Array.from(identities.values(), (item) => item.collectionId),
	)) {
		const rows = await db
			.selectFrom("_emdash_collections")
			.select(["id", "slug"])
			.where("id", "in", batch)
			.execute();
		for (const row of rows) current.add(`${row.id}\u0000${row.slug}`);
	}
	return current;
}

function workLease(work: MediaUsageWorkRecord) {
	if (!work.leaseToken) throw new Error("Claimed media usage work requires a lease token");
	return {
		collectionId: work.collectionId,
		contentId: work.contentId,
		workVersion: work.workVersion,
		leaseToken: work.leaseToken,
	};
}

function workIdentityKey(work: MediaUsageWorkRecord): string {
	return `${work.collectionId}\u0000${work.contentId}\u0000${String(work.workVersion)}`;
}

function workResultKey(work: MediaUsageWorkRecord): string {
	return workIdentityKey(work);
}

function collectionResultKey(work: Pick<MediaUsageWorkRecord, "collectionId" | "collectionSlug">) {
	return `${work.collectionId}\u0000${work.collectionSlug}`;
}

function chunkCollectionIds(ids: readonly string[]): string[][] {
	const unique = [...new Set(ids)];
	const batches: string[][] = [];
	for (let index = 0; index < unique.length; index += 50) {
		batches.push(unique.slice(index, index + 50));
	}
	return batches;
}

function canContinueBulkWork(): boolean {
	const metrics = getRequestContext()?.metrics;
	return !metrics || metrics.dbCount + 150 <= 900;
}

async function isIncrementalCaptureActive(db: Kysely<Database>): Promise<boolean> {
	const row = await db
		.selectFrom("_emdash_media_usage_activation")
		.select("state")
		.where("task_key", "=", "incremental_capture")
		.executeTakeFirst();
	return row?.state === "active";
}

function retryDelaySeconds(attemptCount: number): number {
	const exponential = Math.min(
		MEDIA_USAGE_WORK_PROCESSING_LIMITS.retryMaxSeconds,
		MEDIA_USAGE_WORK_PROCESSING_LIMITS.retryBaseSeconds * 2 ** attemptCount,
	);
	const jitter = Math.floor(
		exponential * MEDIA_USAGE_WORK_PROCESSING_LIMITS.retryJitterRatio * Math.random(),
	);
	return Math.min(MEDIA_USAGE_WORK_PROCESSING_LIMITS.retryMaxSeconds, exponential + jitter);
}

function processingErrorCode(errorCode: ContentMediaUsageRefreshErrorCode | undefined): string {
	if (
		errorCode === "DRAFT_REVISION_NOT_FOUND" ||
		errorCode === "DRAFT_REVISION_MISMATCH" ||
		errorCode === "DRAFT_REVISION_INVALID"
	) {
		return "MEDIA_USAGE_SNAPSHOT_FAILED";
	}
	if (errorCode === "CONTENT_USAGE_GENERATION_CONFLICT") {
		return "MEDIA_USAGE_GENERATION_CONFLICT";
	}
	if (errorCode === "CONTENT_USAGE_RESOURCE_LIMIT") return "MEDIA_USAGE_RESOURCE_LIMIT";
	return "MEDIA_USAGE_PROCESSING_FAILED";
}

export async function runMediaUsageMaintenanceStep(
	db: Kysely<Database>,
): Promise<MediaUsageMaintenanceStepResult> {
	const activation = await db
		.selectFrom("_emdash_media_usage_activation")
		.select(["state", "runtime_generation"])
		.where("task_key", "=", "incremental_capture")
		.executeTakeFirst();
	if (
		activation?.state !== "active" ||
		activation.runtime_generation !== MEDIA_USAGE_ACTIVATION_RUNTIME_GENERATION
	) {
		return runActivationStep(db);
	}
	let blocked = false;
	let blockedReconciliation = false;
	let madeProgress = false;

	for (const taskClass of TASK_CLASSES) {
		const metrics = getRequestContext()?.metrics;
		if (metrics && !canStartMediaUsageMaintenanceStep(metrics)) {
			return madeProgress
				? {
						state: "progress",
						continuation: { kind: "immediate" },
					}
				: {
						state: "blocked",
						continuation: { kind: "immediate" },
					};
		}
		const outcome = await runTaskClass(db, taskClass);
		if (outcome === "inactive") return inactiveResult();
		if (outcome === "progress") madeProgress = true;
		if (outcome === "blocked") {
			blocked = true;
			if (taskClass === "reconciliation") blockedReconciliation = true;
		}
	}
	if (madeProgress) {
		return {
			state: "progress",
			continuation: { kind: "immediate" },
		};
	}

	if (
		blockedReconciliation &&
		(await new MediaUsageReconciliationRepository(db).wakeDrainedBarrierCandidate())
	) {
		return {
			state: "progress",
			continuation: { kind: "immediate" },
		};
	}

	if (blocked) {
		return {
			state: "blocked",
			continuation: { kind: "delayed", delaySeconds: 30 },
		};
	}

	return {
		state: "idle",
		continuation: { kind: "none" },
	};
}

export async function finishMediaUsageCollectionDeletion(
	db: Kysely<Database>,
	collectionSlug: string,
): Promise<MediaUsageCollectionDeletionFinish> {
	const repository = new MediaUsageCollectionDeletionRepository(db);
	const metrics = getRequestContext()?.metrics;
	const firstQuery = metrics?.dbCount ?? 0;
	for (;;) {
		const deletion = await repository.findBySlug(collectionSlug);
		if (!deletion) return { state: "finished" };
		if (deletion.state === "failed") {
			return { state: "failed", collectionId: deletion.collectionId };
		}
		if (
			metrics &&
			(metrics.dbCount - firstQuery >= MEDIA_USAGE_MAINTENANCE_LIMITS.maxStepQueries ||
				!canStartMediaUsageMaintenanceStep(metrics))
		) {
			return { state: "pending" };
		}
		const outcome = await processMediaUsageCollectionDeletion(db, deletion);
		if (outcome === "failed") return { state: "failed", collectionId: deletion.collectionId };
		if (outcome !== "progress" && outcome !== "finalized") return { state: "pending" };
	}
}

async function runActivationStep(db: Kysely<Database>): Promise<MediaUsageMaintenanceStepResult> {
	try {
		const result = await continueMediaUsageActivation(db);
		if (result.outcome === "activating" || result.outcome === "active") {
			return {
				state: "progress",
				continuation: { kind: "immediate" },
			};
		}
		if (result.outcome === "lease_active" || result.outcome === "conflict") {
			return {
				state: "blocked",
				continuation: { kind: "delayed", delaySeconds: 30 },
			};
		}
		return inactiveResult();
	} catch (error) {
		if (error instanceof MediaUsageActivationVersionMismatchError) return inactiveResult();
		throw error;
	}
}

async function runTaskClass(
	db: Kysely<Database>,
	taskClass: MediaUsageMaintenanceTaskClass,
): Promise<"inactive" | "idle" | "blocked" | "progress"> {
	if (taskClass === "entry_work") {
		const result = await processDueMediaUsageWork(db, {
			activationKnownActive: true,
		});
		if (result.claimedCount > 0) return "progress";
		return result.candidateCount > 0 ? "blocked" : "idle";
	}
	if (taskClass === "collection_deletion") {
		const result = await processDueMediaUsageCollectionDeletions(db);
		if (result.claimedCount > 0) return "progress";
		return result.candidateCount > 0 ? "blocked" : "idle";
	}

	const result = await processDueMediaUsageReconciliationDetailed(db, {
		activationKnownActive: true,
	});
	if (result.outcome === "inactive") return "inactive";
	if (result.consumedUnit) return "progress";
	return result.outcome === "claim_lost" || result.hasDeferredCandidate ? "blocked" : "idle";
}

function inactiveResult(): MediaUsageMaintenanceStepResult {
	return {
		state: "inactive",
		continuation: { kind: "none" },
	};
}

function canStartMediaUsageMaintenanceStep(metrics: { dbCount: number }): boolean {
	return (
		metrics.dbCount + MEDIA_USAGE_MAINTENANCE_LIMITS.maxStepQueries <=
		MEDIA_USAGE_MAINTENANCE_LIMITS.eventQueryCeiling
	);
}

export async function repairContentMediaUsageAll(
	db: Kysely<Database>,
): Promise<ContentMediaUsageRepairAllResult> {
	const collections = await loadContentMediaUsageCollectionRecords(db);
	const results: ContentMediaUsageInitialCollectionResult[] = [];

	for (const collection of collections) {
		results.push({
			collection,
			result: await repairContentMediaUsageCollectionSafely(db, collection),
		});
	}

	return aggregateContentMediaUsageRepairAll(
		await filterExistingContentMediaUsageCollectionResults(db, results),
	);
}

export async function scanContentMediaUsageCollection(
	db: Kysely<Database>,
	collectionSlug: string,
	expectedCollectionId?: string,
): Promise<ContentMediaUsageCollectionScan | null> {
	validateIdentifier(collectionSlug, "collection slug");
	let collectionQuery = db
		.selectFrom("_emdash_collections")
		.select("id")
		.where("slug", "=", collectionSlug);
	if (expectedCollectionId !== undefined) {
		collectionQuery = collectionQuery.where("id", "=", expectedCollectionId);
	}
	const collection = await collectionQuery.executeTakeFirst();
	if (!collection) return null;

	const tableName = getContentTableName(collectionSlug);
	const rows = await sql<{ id: string }>`
		SELECT content.id
		FROM ${sql.ref(tableName)} AS content
		WHERE EXISTS (
			SELECT 1
			FROM _emdash_collections AS collection
			WHERE collection.id = ${collection.id}
				AND collection.slug = ${collectionSlug}
		)
		ORDER BY content.id ASC
	`.execute(db);

	return {
		collectionSlug,
		contentIds: rows.rows.map((row) => row.id),
	};
}

export async function repairContentMediaUsageCollection(
	db: Kysely<Database>,
	input: ContentMediaUsageRepairCollectionInput,
): Promise<ContentMediaUsageRepairCollectionResult> {
	validateIdentifier(input.collectionSlug, "collection slug");
	return withContentUsageCollectionLock(input.collectionSlug, () =>
		repairContentMediaUsageCollectionUnlocked(db, input.collectionSlug),
	);
}

async function loadContentMediaUsageCollectionRecords(
	db: Kysely<Database>,
): Promise<ContentMediaUsageCollectionRecord[]> {
	return db
		.selectFrom("_emdash_collections")
		.select(["id", "slug"])
		.orderBy("slug", "asc")
		.execute();
}

async function repairContentMediaUsageCollectionSafely(
	db: Kysely<Database>,
	collection: ContentMediaUsageCollectionRecord,
): Promise<ContentMediaUsageRepairCollectionResult> {
	try {
		return await withContentUsageCollectionLock(collection.slug, () =>
			repairContentMediaUsageCollectionUnlocked(db, collection.slug, collection.id),
		);
	} catch (error) {
		console.error(`[media-usage] Failed to repair collection ${collection.slug}:`, error);
		const now = new Date().toISOString();
		return {
			scope: contentMediaUsageCollectionScope(collection.slug),
			status: "failed",
			indexedSourceCount: 0,
			failedSourceCount: 0,
			skippedSourceCount: 0,
			deletedSourceCount: 0,
			lastErrorCode: CONTENT_MEDIA_USAGE_REPAIR_ERROR.CONTENT_USAGE_REPAIR_ERROR,
			startedAt: now,
			completedAt: now,
		};
	}
}

async function filterExistingContentMediaUsageCollectionResults(
	db: Kysely<Database>,
	results: readonly ContentMediaUsageInitialCollectionResult[],
): Promise<ContentMediaUsageRepairCollectionResult[]> {
	const identityBound = await isIncrementalCaptureActive(db);
	const currentCollections = await loadContentMediaUsageCollectionRecordsSafely(db);
	const currentIdsBySlug = new Map(
		currentCollections.map((collection) => [collection.slug, collection.id]),
	);
	const includedResults: ContentMediaUsageRepairCollectionResult[] = [];
	const excludedResults: ContentMediaUsageInitialCollectionResult[] = [];

	for (const { collection, result } of results) {
		if (currentIdsBySlug.get(collection.slug) === collection.id) {
			includedResults.push(result);
		} else {
			excludedResults.push({ collection, result });
		}
	}

	if (excludedResults.length > 0) {
		const repo = new MediaUsageRepository(db);
		for (const excluded of excludedResults) {
			await repo.deleteIndexStatus(
				excluded.result.scope,
				identityBound ? excluded.collection.id : undefined,
			);
		}
	}

	return includedResults;
}

async function loadContentMediaUsageCollectionRecordsSafely(
	db: Kysely<Database>,
): Promise<ContentMediaUsageCollectionRecord[]> {
	try {
		return await loadContentMediaUsageCollectionRecords(db);
	} catch {
		// Retry once before failing; returning unpruned results can over-report deleted collections.
	}

	try {
		return await loadContentMediaUsageCollectionRecords(db);
	} catch (error) {
		console.error("[media-usage] Failed to reconcile all-content repair collections:", error);
		throw error;
	}
}

function aggregateContentMediaUsageRepairAll(
	collections: readonly ContentMediaUsageRepairCollectionResult[],
): ContentMediaUsageRepairAllResult {
	return {
		status: determineRepairAllStatus(collections),
		collections: [...collections],
		indexedSourceCount: sumCollectionRepairCount(collections, "indexedSourceCount"),
		failedSourceCount: sumCollectionRepairCount(collections, "failedSourceCount"),
		skippedSourceCount: sumCollectionRepairCount(collections, "skippedSourceCount"),
		deletedSourceCount: sumCollectionRepairCount(collections, "deletedSourceCount"),
	};
}

function determineRepairAllStatus(
	collections: readonly ContentMediaUsageRepairCollectionResult[],
): ContentMediaUsageRepairStatus {
	if (collections.length === 0) return "complete";
	if (collections.every((collection) => collection.status === "complete")) return "complete";
	if (collections.some((collection) => collection.status === "stale")) return "stale";
	if (collections.some((collection) => collection.status === "partial")) return "partial";
	if (collections.every((collection) => collection.status === "failed")) return "failed";
	return "partial";
}

function sumCollectionRepairCount(
	collections: readonly ContentMediaUsageRepairCollectionResult[],
	key: "indexedSourceCount" | "failedSourceCount" | "skippedSourceCount" | "deletedSourceCount",
): number {
	return collections.reduce((sum, collection) => sum + collection[key], 0);
}

async function repairContentMediaUsageCollectionUnlocked(
	db: Kysely<Database>,
	collectionSlug: string,
	expectedCollectionId?: string,
): Promise<ContentMediaUsageRepairCollectionResult> {
	const requestedAt = new Date().toISOString();
	const scope = contentMediaUsageCollectionScope(collectionSlug);
	const identityBound = await isIncrementalCaptureActive(db);
	const collection = await loadContentMediaUsageCollectionRecord(db, collectionSlug);
	if (
		!collection ||
		(identityBound && expectedCollectionId && collection.id !== expectedCollectionId)
	) {
		return {
			scope,
			status: "failed",
			indexedSourceCount: 0,
			failedSourceCount: 0,
			skippedSourceCount: 0,
			deletedSourceCount: 0,
			lastErrorCode: CONTENT_MEDIA_USAGE_REPAIR_ERROR.COLLECTION_NOT_FOUND,
			startedAt: requestedAt,
			completedAt: requestedAt,
		};
	}

	const repo = new MediaUsageRepository(db);
	const runToken = ulid();
	let startedAt = requestedAt;
	let execution: ContentMediaUsageRepairExecution | undefined;
	if (identityBound) {
		const run = await repo.beginIndexStatusRepairAtCurrentEpoch({
			...scope,
			collectionId: collection.id,
			runToken,
			schemaVersion: CONTENT_SOURCE_SCHEMA_VERSION,
		});
		if (!run) {
			return {
				scope,
				status: "failed",
				indexedSourceCount: 0,
				failedSourceCount: 0,
				skippedSourceCount: 0,
				deletedSourceCount: 0,
				lastErrorCode: CONTENT_MEDIA_USAGE_REPAIR_ERROR.CONTENT_USAGE_REPAIR_ERROR,
				startedAt,
				completedAt: requestedAt,
			};
		}
		startedAt = run.startedAt;
		execution = { collectionId: collection.id, startingEpoch: run.changeEpoch };
	} else {
		await repo.beginIndexStatusRepair({
			...scope,
			runToken,
			schemaVersion: CONTENT_SOURCE_SCHEMA_VERSION,
			startedAt,
		});
	}

	try {
		const scan = await scanContentMediaUsageCollection(db, collectionSlug, execution?.collectionId);
		if (!scan) {
			const completedAt = new Date().toISOString();
			return await finalizeRepairStatus(db, repo, {
				...scope,
				runToken,
				counts: {
					indexedSourceCount: 0,
					failedSourceCount: 0,
					skippedSourceCount: 0,
					deletedSourceCount: 0,
					lastErrorCode: CONTENT_MEDIA_USAGE_REPAIR_ERROR.COLLECTION_NOT_FOUND,
					missingContentIds: new Set(),
				},
				status: "failed",
				startedAt,
				completedAt,
				execution,
			});
		}
		const counts = await repairScannedContentSources(db, repo, scan, execution?.collectionId);
		const finalScan = await scanContentMediaUsageCollection(
			db,
			collectionSlug,
			execution?.collectionId,
		);
		if (!finalScan) {
			counts.failedSourceCount++;
			counts.lastErrorCode = CONTENT_MEDIA_USAGE_REPAIR_ERROR.COLLECTION_NOT_FOUND;
		} else if (!sameContentIds(repairedContentIds(scan.contentIds, counts), finalScan.contentIds)) {
			markRepairConflict(counts);
		}
		const completedAt = new Date().toISOString();
		const status = determineRepairStatus(counts);
		return await finalizeRepairStatus(db, repo, {
			...scope,
			runToken,
			counts,
			status,
			startedAt,
			completedAt,
			execution,
		});
	} catch (error) {
		if (
			!(error instanceof MediaUsageFieldDiscoveryError) &&
			!(error instanceof MediaUsageBlockResolutionError)
		) {
			console.error(`[media-usage] Failed to repair collection ${collectionSlug}:`, error);
		}
		const completedAt = new Date().toISOString();
		const lastErrorCode =
			error instanceof MediaUsageFieldDiscoveryError
				? error.code
				: error instanceof MediaUsageBlockResolutionError
					? CONTENT_MEDIA_USAGE_REPAIR_ERROR.UNSUPPORTED_BLOCK_DEFINITION
					: CONTENT_MEDIA_USAGE_REPAIR_ERROR.CONTENT_USAGE_REPAIR_ERROR;
		return finalizeRepairStatus(db, repo, {
			...scope,
			runToken,
			counts: {
				indexedSourceCount: 0,
				failedSourceCount: 0,
				skippedSourceCount: 0,
				deletedSourceCount: 0,
				lastErrorCode,
				missingContentIds: new Set(),
			},
			status: "failed",
			startedAt,
			completedAt,
			execution,
		});
	}
}

async function repairScannedContentSources(
	db: Kysely<Database>,
	repo: MediaUsageRepository,
	scan: ContentMediaUsageCollectionScan,
	collectionId?: string,
): Promise<RepairCounts> {
	const counts: RepairCounts = {
		indexedSourceCount: 0,
		failedSourceCount: 0,
		skippedSourceCount: 0,
		deletedSourceCount: 0,
		lastErrorCode: null,
		missingContentIds: new Set(),
	};

	const fieldDiscovery = await loadContentMediaUsageFields(db, scan.collectionSlug, collectionId);
	const observedSources = await repo.findSources(buildContentSourceKeysForScan(scan, collectionId));

	for (const contentId of scan.contentIds) {
		await repairContentSource(
			db,
			repo,
			scan.collectionSlug,
			contentId,
			fieldDiscovery,
			observedSources,
			counts,
			collectionId,
		);
	}

	await reconcileOrphanedContentSources(db, repo, scan.collectionSlug, counts, collectionId);
	return counts;
}

async function repairContentSource(
	db: Kysely<Database>,
	repo: MediaUsageRepository,
	collectionSlug: string,
	contentId: string,
	fieldDiscovery: ContentMediaUsageFieldDiscovery,
	observedSources: Map<string, MediaUsageSource>,
	counts: RepairCounts,
	collectionId?: string,
): Promise<void> {
	const sourceKeys = buildContentSourceKeys(collectionSlug, contentId, collectionId);
	const snapshotsResult = await loadContentMediaUsageSnapshots(
		db,
		collectionSlug,
		contentId,
		fieldDiscovery,
		collectionId ? { collectionId, identityVersion: 1 } : undefined,
	);
	if (!snapshotsResult.success) {
		if (snapshotsResult.error === CONTENT_MEDIA_USAGE_REPAIR_ERROR.CONTENT_NOT_FOUND) {
			markRepairConflict(counts);
			counts.missingContentIds.add(contentId);
			return;
		}
		counts.lastErrorCode = snapshotsResult.error;
		if (snapshotsResult.snapshots) {
			// Partial snapshot failures keep absent variants in place; the attempted source is marked below.
			await repairSnapshotSources(repo, snapshotsResult.snapshots, observedSources, counts);
		}
		if (snapshotsResult.source) {
			const result = await repo.markSourceAttemptedIfMatching(
				{
					...snapshotsResult.source,
					sourceCompleteness: "failed",
					lastErrorCode: snapshotsResult.error,
				},
				observedSources.get(snapshotsResult.source.sourceKey) ?? null,
			);
			if (result.attempted) {
				counts.failedSourceCount++;
			} else {
				markRepairConflict(counts);
			}
			return;
		}

		counts.failedSourceCount++;
		return;
	}

	const expectedSourceKeys = await repairSnapshotSources(
		repo,
		snapshotsResult.snapshots,
		observedSources,
		counts,
	);

	for (const sourceKey of sourceKeys) {
		if (expectedSourceKeys.has(sourceKey)) continue;
		const observedSource = observedSources.get(sourceKey);
		if (!observedSource) continue;
		await deleteObservedSource(repo, sourceKey, observedSource, counts);
	}
}

async function repairSnapshotSources(
	repo: MediaUsageRepository,
	snapshots: readonly ContentMediaUsageSnapshot[],
	observedSources: Map<string, MediaUsageSource>,
	counts: RepairCounts,
): Promise<Set<string>> {
	const expectedSourceKeys = new Set<string>();
	for (const snapshot of snapshots) {
		expectedSourceKeys.add(snapshot.source.sourceKey);
		const result = await repo.replaceSourceIfMatching(
			snapshot.source,
			snapshot.occurrences,
			observedSources.get(snapshot.source.sourceKey) ?? null,
		);
		if (result.replaced || result.unchanged) {
			counts.indexedSourceCount++;
		} else {
			markRepairConflict(counts);
		}
	}
	return expectedSourceKeys;
}

function markRepairConflict(counts: RepairCounts): void {
	counts.skippedSourceCount++;
	counts.lastErrorCode ??= CONTENT_MEDIA_USAGE_REPAIR_ERROR.CONTENT_USAGE_REPAIR_CONFLICT;
}

async function reconcileOrphanedContentSources(
	db: Kysely<Database>,
	repo: MediaUsageRepository,
	collectionSlug: string,
	counts: RepairCounts,
	collectionId?: string,
): Promise<void> {
	const sources = await repo.findCollectionContentSources(collectionSlug, collectionId);
	const existingContentIds = await findExistingContentIds(
		db,
		collectionSlug,
		sources.flatMap((source) => (source.contentId ? [source.contentId] : [])),
		collectionId,
	);

	for (const source of sources) {
		if (!source.contentId) {
			await deleteObservedSource(repo, source.sourceKey, source, counts);
			continue;
		}
		if (existingContentIds.has(source.contentId)) continue;
		await deleteObservedSourceIfContentAbsent(repo, collectionSlug, source, counts);
	}
}

async function findExistingContentIds(
	db: Kysely<Database>,
	collectionSlug: string,
	contentIds: readonly string[],
	collectionId?: string,
): Promise<Set<string>> {
	validateIdentifier(collectionSlug, "collection slug");
	const existingContentIds = new Set<string>();
	const uniqueContentIds = [...new Set(contentIds)];
	if (uniqueContentIds.length === 0) return existingContentIds;

	const tableName = getContentTableName(collectionSlug);
	for (const contentIdBatch of chunks(uniqueContentIds, SQL_BATCH_SIZE)) {
		const result = await sql<{ id: string }>`
			SELECT content.id
			FROM ${sql.ref(tableName)} AS content
			WHERE content.id IN (${sql.join(contentIdBatch)})
			${
				collectionId
					? sql`AND EXISTS (
						SELECT 1
						FROM _emdash_collections AS collection
						WHERE collection.id = ${collectionId}
							AND collection.slug = ${collectionSlug}
					)`
					: sql``
			}
		`.execute(db);
		for (const row of result.rows) {
			existingContentIds.add(row.id);
		}
	}

	return existingContentIds;
}

